WFJ.Data.add("quest", {
  [84135] = { "浜辺のロボット", "岩か何かを使って、メカの部品を外してください。", "午後の波しぶきに半ば隠れるように、奇妙な金属の装置が岸に横たわっている。何かの機械のようだが、これまでに見たことのない代物だ。側面には「D.E.L.T.A.: Deepsea Exploration and Liquefaction Technologies Allianceの所有物」と書かれたラベルがある。開けられそうな小さな収納部も見つけた。", nil, nil, 0x053aeb28, 0xc9fc4eaf, 0x793c2949, nil, nil, "...mm" },
  [84137] = { "機械仕掛けのロマンス", "Guided Buoyancy Accelerantの使い道を見つけてください。", "なぜこの機械がここに墜落していたのか、そしてこの液体は何のためのものなのか、疑問に思う。これを使えば、この謎の組織とつながりがありそうな近くの島々や石油掘削施設にたどり着けるかもしれない。小瓶を開けると、ほのかに酔わせるような果実の香りが鼻をくすぐる。", nil, nil, 0xd205336c, 0x49c78274, 0x0952cd8e, nil, nil, "...mm" },
  [84138] = { "冷たい頼みごと", "Doctor Jurgensの同僚であるWinterspringのNamiに、本の事情を説明してください。", "私はDeepsea Exploration and Liquefaction Technologies Allianceの主任技師にして創設者、そして主任研究員だよ。最新の実験がもうすぐ完成するところで、君の助けが必要なんだ！資源の豊富な次元の位置を特定するための特別な装置を開発中でね。\n\n組み立てを完成させるには、返してもらわなきゃならないものがある。古い同僚のNamiに貸した秘術の公式の本だ。彼女は今もWinterspringで研究を続けているよ。\n\n本を取り戻してくれたら、君を論文の共著者として載せてあげよう！", nil, nil, 0x0198a07f, 0x15c2cb1a, 0xf9463973, nil, nil, "...mm" },
  [84146] = { "Red Bagの憂鬱", "EverlookのNamiがBurning Steppes上空での飛行船の事故で失くしたRed Bagを見つけてください。", "あなたが欲しいものは安全に隠してあるわ。私が探しているものも同じだといいんだけど。\n\n電子光学に使う貴重な工具が入ったred bagを持っていたの。でも、Burning Steppesの上空で飛行船の事故に遭って、それをなくしてしまったのよ！鞄はまだそこにあるかもしれないけど、オークやogre、密猟者がうろついているせいで、仕事を中断せざるを得なかったの。\n\nそれを見つけて持ってきてくれたら、Jurgensの古い本を渡してあげるわ。", nil, nil, 0x1a8943b8, 0xdc3204cc, 0x7cebd737, nil, nil, "...mm" },
  [84147] = { "真剣な申し出", "Winterspring Blood Sampleを15個と20ゴールドを手に入れ、Wildheart Bracers一式と一緒にIronforgeのDelianaのところへ持って行ってください。", "ごきげんよう、{class}。あなたが興味を持ちそうなものがあります。\n\n私の手元に、あなたと同じ職業の者が身につけるものによく似た、しかしはるかに上質な防具一式があります。ちょっとした頼みを聞いていただければ、そのブレイサーを普通のものと交換してさしあげましょう。\n\nWinterspringに棲むfrostsabersや熊の血には、今の私が必要としている性質があります。その血のサンプルをたっぷりと、ブレイサーと少しのゴールドと一緒に持ってきてください。その苦労に見合う価値はあるはずですよ。", nil, nil, 0x5744ae45, 0x8fbd8e2f, 0x9df430b9, nil, nil, "...mm" },
  [84148] = { "真剣な申し出", "Winterspring Blood Sampleを15個と20ゴールドを手に入れ、Beaststalker's Bindings一式と一緒にIronforgeのDelianaのところへ持って行ってください。", "ごきげんよう、{class}。あなたが興味を持ちそうなものがあります。\n\n私の手元に、あなたと同じ職業の者が身につけるものによく似た、しかしはるかに上質な防具一式があります。ちょっとした頼みを聞いていただければ、そのブレイサーを普通のものと交換してさしあげましょう。\n\nWinterspringに棲むfrostsabersや熊の血には、今の私が必要としている性質があります。その血のサンプルをたっぷりと、ブレイサーと少しのゴールドと一緒に持ってきてください。その苦労に見合う価値はあるはずですよ。", nil, nil, 0x5744ae45, 0xdaee3ae5, 0x9df430b9, nil, nil, "...mm" },
