  [84159] = { "真剣な申し出", "Silithus Venom Sampleを15個と20ゴールドを手に入れ、Shadowcraft Bracers一式と一緒にOrgrimmarのMokvarのところへ持って行ってください。", "やあ、{class}！その物腰を見れば、あなたがこの世界で多くを見て、多くを成し遂げてきたことがわかります。それでも、このような防具はまだ見たことがないと賭けてもいいでしょう。\n\nちょっとした頼みを聞いてくれれば、普通のブレイサー一式と交換でこれを譲ってもいいですよ。\n\nSilithusに棲むクモやサソリから採った毒のサンプルがたっぷり必要なのです。それを数枚の金貨と一緒に持ってきてくれれば、交換いたしましょう。", nil, nil, 0x5744ae45, 0xb2f01d1e, 0xea675b9d, nil, nil, "...mm" },
  [84160] = { "真剣な申し出", "Silithus Venom Sampleを15個と20ゴールドを手に入れ、Bindings of the Elements一式と一緒にOrgrimmarのMokvarのところへ持って行ってください。", "やあ、{class}！その物腰を見れば、あなたがこの世界で多くを見て、多くを成し遂げてきたことがわかります。それでも、このような防具はまだ見たことがないと賭けてもいいでしょう。\n\nちょっとした頼みを聞いてくれれば、普通のブレイサー一式と交換でこれを譲ってもいいですよ。\n\nSilithusに棲むクモやサソリから採った毒のサンプルがたっぷり必要なのです。それを数枚の金貨と一緒に持ってきてくれれば、交換いたしましょう。", nil, nil, 0x5744ae45, 0x42654b5d, 0xea675b9d, nil, nil, "...mm" },
  [84161] = { "真剣な申し出", "Silithus Venom Sampleを15個と20ゴールドを手に入れ、Dreadmist Bracers一式と一緒にOrgrimmarのMokvarのところへ持って行ってください。", "やあ、{class}！その物腰を見れば、あなたがこの世界で多くを見て、多くを成し遂げてきたことがわかります。それでも、このような防具はまだ見たことがないと賭けてもいいでしょう。\n\nちょっとした頼みを聞いてくれれば、普通のブレイサー一式と交換でこれを譲ってもいいですよ。\n\nSilithusに棲むクモやサソリから採った毒のサンプルがたっぷり必要なのです。それを数枚の金貨と一緒に持ってきてくれれば、交換いたしましょう。", nil, nil, 0x5744ae45, 0x7f9ef117, 0xea675b9d, nil, nil, "...mm" },
  [84162] = { "真剣な申し出", "Silithus Venom Sampleを15個と20ゴールドを手に入れ、Bracers of Valor一式と一緒にOrgrimmarのMokvarのところへ持って行ってください。", "やあ、{class}！その物腰を見れば、あなたがこの世界で多くを見て、多くを成し遂げてきたことがわかります。それでも、このような防具はまだ見たことがないと賭けてもいいでしょう。\n\nちょっとした頼みを聞いてくれれば、普通のブレイサー一式と交換でこれを譲ってもいいですよ。\n\nSilithusに棲むクモやサソリから採った毒のサンプルがたっぷり必要なのです。それを数枚の金貨と一緒に持ってきてくれれば、交換いたしましょう。", nil, nil, 0x5744ae45, 0x9ca9a24b, 0xea675b9d, nil, nil, "...mm" },
  [84172] = { "順当な報酬", "Beaststalker's BeltとBeaststalker's Gloves一式を、OrgrimmarのMokvarのところへ持って行ってください。", "あなたはとても信頼できる方だとわかりました、{name}。この苦境を乗り越えるのにあなたが力を貸してくれると信じてはいますが、働きに応じて報いるのが賢明でしょう。\n\nひとまず、あなたのベルトと手袋を交換しましょう。二人でこれをやり遂げたら、残りの品もお渡しできるようにします。", nil, nil, 0x467758ec, 0xf910b600, 0xd0d70463, nil, nil, "...mm" },
  [84176] = { "順当な報酬", "Cord of the ElementsとGauntlets of the Elements一式を、OrgrimmarのMokvarのところへ持って行ってください。", "あなたはとても信頼できる方だとわかりました、{name}。この苦境を乗り越えるのにあなたが力を貸してくれると信じてはいますが、働きに応じて報いるのが賢明でしょう。\n\nひとまず、あなたのベルトとガントレットを交換しましょう。二人でこれをやり遂げたら、残りの品もお渡しできるようにします。", nil, nil, 0x467758ec, 0xefd34ff4, 0x8e2fd8f3, nil, nil, "...mm" },
  [84211] = { "密猟者の隠れ家", "残りの材料を取り戻し、EverlookのNamiのところへ戻ってください。", "鞄を拾い上げると、すぐにほとんど空っぽだと気づく。どういうわけか、Namiは鞄だけでは本と交換してくれないような気がする。だが、空っぽでないものがある。この野営地だ。身を守りつつ、こうした品がほかにもないか目を光らせておいたほうがいい。", nil, nil, 0x365bdf4a, 0x9c5b921e, 0xe8f51841, nil, nil, "...mm" },
  [84212] = { "大急ぎで引き返す", "Jurgensが探していた本を持って、D.E.L.T.Aの研究所へ戻ってください。", "NamiがJurgensの本を手渡してくれた。それを安全にしまい込むと、世界の反対側へ戻る長い旅が始まる。", nil, nil, 0x4001a614, 0xb93dc5d0, 0x0972fb70, nil, nil, "...mm" },
  [84213] = { "裂け目の彼方へ", "Distant Communication Deviceを使い、Tirisfal GladesかWestfallにいるJurgensに合図を送ってください。\nそれから、彼が電気送信機の性能を実演するのを手伝ってください。", "この歴史的な実験に参加して、私の発明の驚異を目撃してくれ！適切な地熱バイオフラックスエネルギーを持つ地点を2つ算出した。手動自動ロック式フェイザーで、互換性のある領域内の座標へ私たちを送る準備はできている。\n\n互換性のある座標に着いたら、この遠隔トランスポンダーで私に信号を送ってくれ。ワープ送信機を設定して、ここと向こうの間の空間を折り畳むから。\n\nつまり、君が準備できたと言ったら、向こうで会おうってことさ！", nil, nil, 0x24449cae, 0xbca503f9, 0x45659c4e, nil, nil, "...mm" },
  [84318] = { "おい！", "Corrin's CrossingでOrthasのなくなったハンマーを見つけてください。", "おい！{class}！そうだ、お前だ！わしが長年入っとった、あの陰気なボロボロの肉の着ぐるみをぶっ壊してくれたのはありがたいが、どうもあの世へ行く気になれんのだ。たぶん、旅立つ前に片付けにゃならん「Unfinished Business」があるからだろう。というわけで、間抜けめ、お前は手伝いに徴用されたぞ！\n\nわしのハンマーを取ってきてくれ。Corrin's Crossingのどこかにあるはずだ。見逃しようがないぞ。\n\nおい、これも持っていけ。わしのお気に入りの金歯だ。わしの武器を見つけたら、そいつをこすってくれ。", nil, nil, 0x0014e5a3, 0x4d04ade1, 0x5edb9620, nil, nil, "...mm" },
  [84319] = { "そうはさせんぞ！", "OrthasはPlaguewoodのどこかにいるAbominationの死体から、失くした鎧を取り戻してほしいと言っています。", "ハンマーはよくやってくれた、{class}。次はわしの鎧だ。あの世へ行くには、どうしてもあれを取り戻さにゃならん。\n\n困ったことに、そいつは、えー……あのabominationsの一体の腹の中にあるんだ。わかっとる、わかっとる、無茶な頼みだってのは。だが、わかってくれ、わしはかつて山の下の偉大な領主だったんだ！わしの一族に代々伝わる鎧が、腐りかけた巨大な肉の山の腹の汁で溶けていくと知りながら、あの世へ行くことなどできるもんか！", nil, nil, 0x3864f2c9, 0x0ff14544, 0x075b11be, nil, nil, "...mm" },
  [84330] = { "ちょっとした死霊術", "StratholmeのMaleki the PallidからNecrotic Runestoneを手に入れ、Eastern Plaguelands南西部のUndercroft付近にあるRotting Dwarf Corpseを見つけてください。", "つまりだな、ちょうどいいドワーフの死体を見つけて、そいつにちょいと儀式をして、わしの魂を地に繋ぎ止めにゃならん。そうすりゃわしは旅立てる！どれも至って普通のことさ、もちろん！それと、死霊術師みたいな奴が持っとるNecrotic Runestoneも少し要る。もちろんな。Stratholmeに、Maleki the Pallidって名の奴がおる。素直に手放してくれるとは思えんが、それには手があるってもんよ！\n\nその石を手に入れたら、地下聖堂へ向かえ。そこにある死体なら使えるはずだ！", nil, nil, 0xe2d2d338, 0x2df4d6f8, 0xb119cbe0, nil, nil, "...mm" },
  [84332] = { "領主の感謝", nil, "<小さな箱に触れると、頭の中に実体のない声が聞こえてくる>\n\nどれだけ感謝してもしきれんよ、{name}。お前さんが思っとったような結末じゃなかったろうがな！あまりむくれんように、わしにはもう用のない、お前さんの役に立ちそうなもんをやろう。\n\n達者でな、{name}。ああ、最後にひとつ……近いうちに、遠くに浮かぶ巨大なネクロポリスを見かけたら、わしならしっぽを巻いて逃げ出すね。ハッ！", nil, nil, 0x365c1fc6, nil, 0x13d01d2e, nil, nil, ".m.mm" },
  [84338] = { "拘束力のある契約", "Sulfuronの設計図を受け取りたいなら、Thorium Brotherhood ContractをLokhtos Darkbargainerに渡して下さい。", "署名者は、Thorium Brotherhood（TB Ltd.）へ納品するSulfuronのインゴットが本物であり、その模造品ではないことをここに宣言する。また署名者は、Sulfurasの製作、鍛造、発見、創造、販売、あるいは摂取を試みた結果として本人に生じるいかなる損害も、TB Ltd.の責任または過失ではないことを了承する。\n\nこの契約書に署名することにより、あなたはここに記載されたすべての条項に同意したものとする。\n\n_________________\n\n署名", nil, nil, 0xb3e013a8, 0xb4f357b1, 0x9f3945b5, nil, nil, "...mm", nil, nil, 0xc22a16e9, nil, nil },
  [84377] = { "Dark Hordeの終焉", "Head of Rend BlackhandをStormwindのMaster Mathias Shawのところへ持って行ってください。", "事は成された。Dark Hordeの大族長、Dal'rend Blackhandは足元で息絶えている。\n\n彼の首を取り、Master Shawのもとへ届けよう。", nil, nil, 0x3409b38a, 0xb41d6d2b, 0x6335af8e, nil, nil, "...mm" },
  [84394] = { "図書館の偉大なる友", nil, nil, nil, nil, 0xf10ee12c, nil, nil, nil, nil, ".mmmm" },
  [84395] = { "Undead Potatoes", nil, nil, nil, nil, 0xe94bc437, nil, nil, nil, nil, ".mmmm" },
