  [84402] = { "Necromancy 101", nil, nil, nil, nil, 0xaebf1ec4, nil, nil, nil, nil, ".mmmm" },
  [84414] = { "わしを送り出してくれ", "Orthasがこの世を去るのを見届けてください。", "<頭の中にOrthasの実体のない声が聞こえてくる>\n\nさあ、着いたぞ。さっさと始めようじゃないか、なあ？", nil, nil, 0x415fa18d, 0x9da87f05, 0xbcfbb7e3, nil, nil, "...mm" },
  [84495] = { "Fiery Plate Gauntlets", "Enchanted Thorium Barsを$N1個、Essence of Fireを$N2個、Star Rubiesを$N3個、Malyfous Darkhammerのところへ持って行って下さい。Unfired Plate Gauntletsも渡す必要がある。", "Thaurissanの髭にかけて！\n\nどこでそれを見つけたんだ？\n\nそれより、それを手放す気はあるか？ もちろん、そんな気高い心遣いには礼をするぞ。\n\nこうしよう、{name}。そのunfired gauntletsを譲ってくれたら、お前さん自身の一式を作る方法を教えてやる。正確なレシピを絞り込めるように、材料を集めてきてくれるだけでいい。\n\n取引成立か？？\n\n必要なもののリストはこれだ。お前さんがgauntletsを提供してくれるんだから、エンチャントされていないthoriumはわしが自腹で用意しよう。", nil, nil, 0x4cbb6a5e, 0x5de76819, 0xccc5a0a0, nil, nil, "...mm" },
  [84555] = { "Nostro's Compendium", "Nostro's Compendium of Dragon SlayingをAthenaeumへ返してください。", "きわめて重要なものを見つけた。この本は、これまでに見たどの本とも違う。\n\n何者か、あるいは何かが、Athenaeumの封印を打ち破ったようだ。中の文章は乱れていて、ほとんど読めない。", nil, nil, 0xd019ffa4, 0x30367b5a, 0x9a80f073, nil, nil, "...mm" },
})
